ALTER TABLE public.interactive_hotspots ADD CONSTRAINT interactive_hotspots_height_check CHECK (((height IS NULL) OR ((height > (0)::numeric) AND (height <= (1)::numeric))));
ALTER TABLE public.interactive_hotspots ADD CONSTRAINT interactive_hotspots_hotspot_type_check CHECK ((hotspot_type = ANY (ARRAY['marker'::text, 'model'::text, 'info'::text, 'ar_scene'::text])));
