ALTER TABLE public.interactive_hotspots ADD CONSTRAINT interactive_hotspots_width_check CHECK (((width IS NULL) OR ((width > (0)::numeric) AND (width <= (1)::numeric))));
ALTER TABLE public.interactive_hotspots ADD CONSTRAINT interactive_hotspots_x_check CHECK (((x >= (0)::numeric) AND (x <= (1)::numeric)));
ALTER TABLE public.interactive_hotspots ADD CONSTRAINT interactive_hotspots_y_check CHECK (((y >= (0)::numeric) AND (y <= (1)::numeric)));
ALTER TABLE public.legend_pages ADD CONSTRAINT valid_page_number CHECK ((page_number > 0));
ALTER TABLE public.legend_source_documents ADD CONSTRAINT legend_source_documents_render_status_check CHECK ((render_status = ANY (ARRAY['not_rendered'::text, 'rendering'::text, 'ready'::text, 'failed'::text])));
