ALTER TABLE public.physical_editions ADD CONSTRAINT physical_editions_code_quota_check CHECK ((code_quota >= 0));
ALTER TABLE public.physical_editions ADD CONSTRAINT valid_release_year CHECK (((release_year IS NULL) OR (release_year >= 1900)));
ALTER TABLE public.products ADD CONSTRAINT valid_product_price CHECK ((price >= (0)::numeric));
